import{_ as t,o,c as d,a2 as a}from"./chunks/framework.CvydjLy7.js";const _=JSON.parse('{"title":"六、常见问题","description":"","frontmatter":{"title":"六、常见问题"},"headers":[],"relativePath":"ch02/06.md","filePath":"ch02/06.md","lastUpdated":1789497795000}'),r={name:"ch02/06.md"};function c(n,e,i,s,l,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="六、常见问题" tabindex="-1">六、常见问题 <a class="header-anchor" href="#六、常见问题" aria-label="Permalink to &quot;六、常见问题&quot;">​</a></h1><table tabindex="0"><thead><tr><th>症状</th><th>原因与解法</th></tr></thead><tbody><tr><td>接口 404，启动日志正常且没报错</td><td>控制器不在主类的包路径下。检查包名是否为主类包的多级子包（<code>com.example.activity.web</code> ✓，<code>com.example.web</code> ✗）</td></tr><tr><td>启动日志里 <code>Found 0 JPA repository interfaces</code></td><td>仓库接口不在扫描路径内，或接口没有继承 <code>Repository</code> 体系的接口</td></tr><tr><td>报 <code>required a single bean, but N were found</code></td><td>同类型多个候选 Bean。用 <code>@Primary</code> 或 <code>@Qualifier</code>，或重新审视设计</td></tr><tr><td>报 <code>No qualifying bean of type ... available</code></td><td>该类型的 Bean 根本没注册。检查类上有没有构造型注解、包是否被扫描到</td></tr><tr><td>报 <code>BeanCurrentlyInCreationException</code> / 循环依赖</td><td>两个 Bean 构造器互相依赖。通常是设计问题：把公共部分抽到第三个类，或用 <code>@Lazy</code> 打破（治标不治本）</td></tr><tr><td>配置类里的 <code>@Bean</code> 方法每次调用都创建新对象</td><td>类上漏了 <code>@Configuration</code>，或用了 <code>proxyBeanMethods = false</code> 却仍按单例假设使用</td></tr><tr><td>改了 <code>application.yml</code> 但配置没生效</td><td>文件位置不对（必须在 <code>src/main/resources</code> 下）、缩进有误、或同名配置在更高优先级的来源里被覆盖（第 3 篇讲优先级）</td></tr></tbody></table><blockquote><p><strong>下一篇要做什么</strong></p><p>结构立起来了，接下来解决“配置管理”这件事。下一篇对照官方的 <em>Externalized Configuration</em>、<em>Profiles</em> 与 <em>Logging</em> 章节，讲清楚配置的十来个来源与优先级、<code>@ConfigurationProperties</code> 的正确用法、多环境配置的分离策略，以及日志怎么配才既方便排查又不淹没信息。</p></blockquote>',3)])])}const u=t(r,[["render",c]]);export{_ as __pageData,u as default};
